#!/usr/bin/env python3
from __future__ import annotations

import argparse
import random
from pathlib import Path

from ntru import NTRUParams, bytes_to_poly_blocks, decrypt, encrypt, keygen


SECURITY_LEVEL = "toy-256"
DEFAULT_PARAMS = NTRUParams(N=127, p=3, q=12289, df=7, dg=7, dr=6, chunk_bytes=24)


def read_flag(path: Path) -> bytes:
    data = path.read_bytes().strip()
    if not data.startswith(b"flag{") or not data.endswith(b"}"):
        raise ValueError("flag must use flag{...} format")
    return data


def write_public_key(path: Path, params: NTRUParams, h: list[int]) -> None:
    path.write_text(
        "\n".join(
            [
                f"SECURITY_LEVEL = {SECURITY_LEVEL!r}",
                f"N = {params.N}",
                f"p = {params.p}",
                f"q = {params.q}",
                f"h = {h!r}",
                "",
            ]
        ),
        encoding="utf-8",
    )


def write_output(path: Path, ciphertexts: list[list[int]]) -> None:
    path.write_text(f"ciphertexts = {ciphertexts!r}\n", encoding="utf-8")


def build_challenge(flag: bytes, params: NTRUParams, rng: random.Random) -> tuple[list[int], list[list[int]]]:
    messages = bytes_to_poly_blocks(flag, params.N, params.chunk_bytes)
    for _ in range(500):
        public_key, private_key = keygen(params, rng)
        ciphertexts = []
        ok = True
        for message in messages:
            for _ in range(200):
                ciphertext = encrypt(message, public_key, params, rng)
                if decrypt(ciphertext, private_key, params) == message:
                    ciphertexts.append(ciphertext)
                    break
            else:
                ok = False
                break
        if ok:
            return public_key.h, ciphertexts
    raise RuntimeError("failed to generate a stable challenge instance")


def main() -> None:
    parser = argparse.ArgumentParser(description="Generate TinyNTRU challenge files.")
    parser.add_argument("--flag", type=Path, default=Path("flag.txt"))
    parser.add_argument("--out", type=Path, default=Path("."))
    args = parser.parse_args()

    rng = random.SystemRandom()
    flag = read_flag(args.flag)
    h, ciphertexts = build_challenge(flag, DEFAULT_PARAMS, rng)

    args.out.mkdir(parents=True, exist_ok=True)
    write_public_key(args.out / "public_key.txt", DEFAULT_PARAMS, h)
    write_output(args.out / "output.txt", ciphertexts)


if __name__ == "__main__":
    main()

