#!/usr/bin/env python3
from __future__ import annotations

import random
from typing import NamedTuple


class NTRUParams(NamedTuple):
    N: int = 127
    p: int = 3
    q: int = 12289
    df: int = 7
    dg: int = 7
    dr: int = 6
    chunk_bytes: int = 24


class PublicKey(NamedTuple):
    h: list[int]


class PrivateKey(NamedTuple):
    f: list[int]
    g: list[int]


def _trim(poly: list[int], n: int) -> list[int]:
    return (poly + [0] * n)[:n]


def mod_center(x: int, modulus: int) -> int:
    x %= modulus
    if x > modulus // 2:
        x -= modulus
    return x


def center_lift(poly: list[int], modulus: int) -> list[int]:
    return [mod_center(x, modulus) for x in poly]


def poly_add(a: list[int], b: list[int], n: int, modulus: int | None = None) -> list[int]:
    out = [(_trim(a, n)[i] + _trim(b, n)[i]) for i in range(n)]
    if modulus is not None:
        out = [x % modulus for x in out]
    return out


def poly_mul(a: list[int], b: list[int], n: int, modulus: int | None = None) -> list[int]:
    a = _trim(a, n)
    b = _trim(b, n)
    out = [0] * n
    for i, ai in enumerate(a):
        if ai == 0:
            continue
        for j, bj in enumerate(b):
            if bj:
                out[(i + j) % n] += ai * bj
    if modulus is not None:
        out = [x % modulus for x in out]
    return out


def _inv_mod(x: int, modulus: int) -> int:
    return pow(x % modulus, -1, modulus)


def _solve_mod(matrix: list[list[int]], target: list[int], modulus: int) -> list[int]:
    n = len(target)
    aug = [[matrix[r][c] % modulus for c in range(n)] + [target[r] % modulus] for r in range(n)]
    row = 0
    for col in range(n):
        pivot = None
        for r in range(row, n):
            if aug[r][col] % modulus:
                pivot = r
                break
        if pivot is None:
            continue
        aug[row], aug[pivot] = aug[pivot], aug[row]
        inv = _inv_mod(aug[row][col], modulus)
        aug[row] = [(v * inv) % modulus for v in aug[row]]
        for r in range(n):
            if r == row:
                continue
            factor = aug[r][col] % modulus
            if factor:
                aug[r] = [(aug[r][c] - factor * aug[row][c]) % modulus for c in range(n + 1)]
        row += 1
    if row != n:
        raise ValueError("polynomial is not invertible")
    return [aug[i][-1] % modulus for i in range(n)]


def poly_inv(poly: list[int], n: int, modulus: int) -> list[int]:
    poly = _trim(poly, n)
    matrix = [[poly[(r - c) % n] for c in range(n)] for r in range(n)]
    target = [1] + [0] * (n - 1)
    inv = _solve_mod(matrix, target, modulus)
    if poly_mul(inv, poly, n, modulus) != target:
        raise ValueError("inverse verification failed")
    return inv


def sample_sparse_ternary(n: int, weight: int, rng: random.Random, avoid_zero: bool = False) -> list[int]:
    positions = list(range(1 if avoid_zero else 0, n))
    chosen = rng.sample(positions, weight)
    rng.shuffle(chosen)
    pos_count = (weight + 1) // 2
    poly = [0] * n
    for idx, coeff_index in enumerate(chosen):
        poly[coeff_index] = 1 if idx < pos_count else -1
    return poly


def keygen(params: NTRUParams, rng: random.Random) -> tuple[PublicKey, PrivateKey]:
    while True:
        F = sample_sparse_ternary(params.N, params.df, rng, avoid_zero=True)
        G = sample_sparse_ternary(params.N, params.dg, rng)
        f = [0] * params.N
        f[0] = 1
        f = poly_add(f, [params.p * x for x in F], params.N)
        g = [params.p * x for x in G]
        try:
            finv_q = poly_inv(f, params.N, params.q)
        except ValueError:
            continue
        h = poly_mul(finv_q, g, params.N, params.q)
        return PublicKey(h), PrivateKey(f, g)


def encrypt(message: list[int], public_key: PublicKey, params: NTRUParams, rng: random.Random) -> list[int]:
    r = sample_sparse_ternary(params.N, params.dr, rng)
    noisy = poly_mul(r, public_key.h, params.N, params.q)
    return poly_add(noisy, _trim(message, params.N), params.N, params.q)


def decrypt(ciphertext: list[int], private_key: PrivateKey, params: NTRUParams) -> list[int]:
    lifted = center_lift(poly_mul(private_key.f, ciphertext, params.N, params.q), params.q)
    return [x % params.p for x in lifted]


